def comps(gg,col=None):
    H,W=len(gg),len(gg[0]); seen=set(); out=[]
    cells_by_col={}
    for i in range(H):
        for j in range(W):
            c=gg[i][j]
            if col is not None and c!=col: continue
            if (i,j) in seen: continue
            q=deque([(i,j)]); seen.add((i,j)); cc=[]
            while q:
                y,x=q.popleft(); cc.append((y,x))
                for dy in(-1,0,1):
                    for dx in(-1,0,1):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and gg[ny][nx]==c and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
            ys=[a for a,b in cc]; xs=[b for a,b in cc]
            r0,c0=min(ys),min(xs); hh=max(ys)-r0+1; ww=max(xs)-c0+1
            out.append((cc,(r0,c0,hh,ww)))
    return out
def solve(gi):
    bgv=Counter(v for r_ in gi for v in r_).most_common(1)[0][0]
    cols=sorted(((sum(1 for r_ in gi for v in r_ if v==c),c) for c in set(v for r_ in gi for v in r_) if c!=bgv),reverse=True)
    tg=cols[0][1]
    best=None
    for cc,(r0,c0,hh,ww) in comps(gi,tg):
        area=len(cc)
        if best is None or area>best[0]: best=(area,(r0,c0,hh,ww))
    _,(r0,c0,hh,ww)=best
    cnt=Counter(v for r_ in gi[r0:r0+hh] for v in r_[c0:c0+ww])
