    stray=sum(1 for a in range(hh) for b in range(ww) if gi[r0+a][c0+b] not in (tg,bgv))
    return [[tg if gi[r0+a][c0+b] not in (bgv,) else gi[r0+a][c0+b] for b in range(ww)] for a in range(hh)],(r0,c0,hh,ww),tgt_cnt,stray,len(gi)*len(gi[0])
